import os
from abc import ABCMeta

import requests
from six import add_metaclass

from hran_pacman.bases.wft_base import WFTDownloader
from hran_pacman.exceptions import InvalidBuildException


@add_metaclass(ABCMeta)
class FDSWDownloader(WFTDownloader):
    def __init__(self, baseline):
        """
        Package downloader for FDSW
        :param baseline: package baseline
        """
        self.baseline = baseline
        self.package = self.get_downloadable_file()
        self._package_name = os.path.split(self.package.url)[-1]
        super(FDSWDownloader, self).__init__(baseline)

    def get_sm_url(self):
        """
        Returns downloadable sm file url
        :return: sm url
        """
        package = next(iter(filter(lambda f: "BTSSM" in f.name, self.files)), None)
        if package is None:
            raise InvalidBuildException("Did not find downloadable file")
        return package.url

    def get_software_package(self):
        """
        Method downloads software package to current working directory
        """
        data = requests.get(self.package.url, stream=True)
        self._stream_to_file(self.package_name, data)

    @property
    def package_name(self):
        return self._package_name
